import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMT算子性能优化","link":"/guide/operator_practice/simt_operator_optimization/simt_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simt_operator_optimization/memory_access/memory_access_merge"},{"text":"通过类型对齐提升搬运效率","link":"/guide/operator_practice/simt_operator_optimization/memory_access/type_alignment_transfer"}]},"headers":[],"relativePath":"guide/operator_practice/simt_operator_optimization/memory_access/type_alignment_transfer.md","filePath":"guide/operator_practice/simt_operator_optimization/memory_access/type_alignment_transfer.md","lastUpdated":1787539935000}'),t={name:"guide/operator_practice/simt_operator_optimization/memory_access/type_alignment_transfer.md"};function l(e,s,o,i,d,r){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>通过类型对齐提升搬运效率</h1><p>【优先级】中</p><p>【描述】SIMT编程模式下，结构体类型对齐会影响Global Memory的访存效率。<span data-filter="950">Ascend 950PR/Ascend 950DT支持1B、2B、4B、8B、16B五种位宽的访存指令。</span>在数据总量不变时，可通过类型对齐到更大的位宽，提升数据搬运效率。</p><p>【样例介绍】设置总搬运量<code>MEM_BYTES</code>为512MiB，构造多组不同大小、不同对齐方式的结构体<code>TData</code>，依次将长度为<code>num_elements</code>的输入数组<code>d_idata</code>整体复制到输出数组<code>d_odata</code>进行测试，对比非对齐与使用<code>alignas</code>类型对齐后的耗时差异。具体代码可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/03_best_practices/00_memory_optimizations/aligned_types">类型对齐优化搬运效率最佳实践样例</a>，其中核函数（Kernel）实现如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">THREAD_COUNT</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2048</span><span class="p">;</span><span class="w">                  </span><span class="c1">// threads per block</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">size_t</span><span class="w"> </span><span class="n">MEM_BYTES</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">512ULL</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024ULL</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024ULL</span><span class="p">;</span><span class="w"> </span><span class="c1">// 总数据量512 MiB</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">num_elements</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">MEM_BYTES</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">TData</span><span class="p">));</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">class</span><span class="w"> </span><span class="nc">TData</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__launch_bounds__</span><span class="p">(</span><span class="n">THREAD_COUNT</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">aligned_type_kernel</span><span class="p">(</span>
<span class="w">    </span><span class="n">TData</span><span class="o">*</span><span class="w"> </span><span class="n">d_odata</span><span class="p">,</span><span class="w"> </span><span class="n">TData</span><span class="o">*</span><span class="w"> </span><span class="n">d_idata</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">num_elements</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">num_threads</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">pos</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tid</span><span class="p">;</span><span class="w"> </span><span class="n">pos</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">num_elements</span><span class="p">;</span><span class="w"> </span><span class="n">pos</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">num_threads</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">d_odata</span><span class="p">[</span><span class="n">pos</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">d_idata</span><span class="p">[</span><span class="n">pos</span><span class="p">];</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>下面以<code>Align4</code>、<code>Misalign4</code>这两个结构体作为典型代表展示对照场景。</p><p>【反例】<code>Misalign4</code>未设置显式对齐，默认<code>alignof</code>受字段类型限制，编译器只能选用窄位宽的访存指令。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">Misalign4</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="n">r</span><span class="p">,</span><span class="w"> </span><span class="n">g</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">;</span>
<span class="p">};</span><span class="w"> </span><span class="c1">// sizeof=4, alignof=1</span>
</code></pre></div><p>性能数据如下：</p><table><thead><tr><th align="center">Task Duration(us)</th><th align="center">aiv_total_cycles</th></tr></thead><tbody><tr><td align="center">81223.02</td><td align="center">134028903.60</td></tr></tbody></table><p>上述结构体由字段类型决定<code>alignof=1</code>，编译器只能用8-bit档位搬运每个元素，<code>aiv_total_cycles</code>和<code>Task Duration</code>都较高。</p><p>【正例】使用<code>alignas</code>提升对齐属性，编译器可以选用更宽位宽的访存指令。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">alignas</span><span class="p">(</span><span class="mi">4</span><span class="p">)</span><span class="w"> </span><span class="n">Align4</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="n">r</span><span class="p">,</span><span class="w"> </span><span class="n">g</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">;</span>
<span class="p">};</span><span class="w"> </span><span class="c1">// sizeof=4, alignof=4</span>
</code></pre></div><p>性能数据如下：</p><table><thead><tr><th align="center">Task Duration(us)</th><th align="center">aiv_total_cycles</th></tr></thead><tbody><tr><td align="center">27889.33</td><td align="center">46005213.32</td></tr></tbody></table><p><code>Align4</code>将<code>alignof</code>从1B提升到4B，编译器可以选用32-bit档位完成单元素搬运，<code>aiv_total_cycles</code>和<code>Task Duration</code>都显著减小。</p><p>对比多组结构体大小不同的样例，在类型对齐前后耗时差异如下：</p><table><thead><tr><th align="center">结构体大小</th><th align="center">对齐Task Duration(us)</th><th align="center">非对齐Task Duration(us)</th><th align="center">非对齐Task Duration/对齐Task Duration</th></tr></thead><tbody><tr><td align="center">4B (4×u8)</td><td align="center">27889.33 (alignof=4)</td><td align="center">81223.02 (alignof=1)</td><td align="center"><strong>2.91x</strong></td></tr><tr><td align="center">4B (2×u16)</td><td align="center">27833.56 (alignof=4)</td><td align="center">46656.61 (alignof=2)</td><td align="center"><strong>1.68x</strong></td></tr><tr><td align="center">4B (2×u8 + u16)</td><td align="center">27854.56 (alignof=4)</td><td align="center">46666.11 (alignof=2)</td><td align="center"><strong>1.68x</strong></td></tr><tr><td align="center">4B (u8 + 1B padding + u16)</td><td align="center">27809.72 (alignof=4)</td><td align="center">46664.42 (alignof=2)</td><td align="center"><strong>1.68x</strong></td></tr><tr><td align="center">8B</td><td align="center">17417.23 (alignof=8)</td><td align="center">21287.91 (alignof=4)</td><td align="center"><strong>1.22x</strong></td></tr><tr><td align="center">16B</td><td align="center">27931.29 (alignof=16)</td><td align="center">38353.60 (alignof=4)</td><td align="center"><strong>1.37x</strong></td></tr><tr><td align="center">32B</td><td align="center">52357.78 (alignof=32)</td><td align="center">77790.93 (alignof=4)</td><td align="center"><strong>1.49x</strong></td></tr></tbody></table><p>测试结果表明：<strong>在数据总量不变的时候，相同大小的结构体，类型对齐可以提升搬运效率</strong>。以4B结构体为例，随着结构体类型对齐位宽从1B对齐提升至4B，<code>非对齐Task Duration/对齐Task Duration</code>逐步下降，说明非对齐与对齐的耗时差距逐步缩小。此外，同大小的4B结构体，字段组合形式、有无填充位，都不会对搬运效率产生影响。</p><p>【总结】SIMT算子使用结构体搬运数据时，结构体类型对齐能让访存指令以更大位宽合并完成搬运，降低搬运耗时。<span data-filter="950">Ascend 950PR/Ascend 950DT支持1B、2B、4B、8B、16B位宽的访存指令，因此建议使用时在不超过结构体大小的情况下，尽量选择更高的位宽。</span></p></article></div>`,1)])])}const h=a(t,[["render",l]]);export{_ as __pageData,h as default};
